import{_ as o,o as a,c as r,ag as e}from"./chunks/framework.B5ULsuav.js";const c=JSON.parse('{"title":"如何开始实修","description":"","frontmatter":{},"headers":[],"relativePath":"20-专题研究/topic-入门实修.md","filePath":"20-专题研究/topic-入门实修.md","lastUpdated":1778155802000}'),l={name:"20-专题研究/topic-入门实修.md"};function u(i,t,q,n,h,s){return a(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="如何开始实修" tabindex="-1">如何开始实修 <a class="header-anchor" href="#如何开始实修" aria-label="Permalink to &quot;如何开始实修&quot;">​</a></h1><blockquote><p>专题分析：初学者实修入门指南 组合模型：自然务实 + 对境不住 + 性命双修</p></blockquote><hr><h2 id="一、总纲-了空居士的四条修行原则" tabindex="-1">一、总纲：了空居士的四条修行原则 <a class="header-anchor" href="#一、总纲-了空居士的四条修行原则" aria-label="Permalink to &quot;一、总纲：了空居士的四条修行原则&quot;">​</a></h2><p>了空居士在答疑中反复强调，跟他修炼的核心方法极其简单，只有四条：</p><blockquote><p><strong>&quot;与我修炼其实方法非常简单：与人为善，观察自己的念头。正确的给予肯定，错误的给予否定，解不开的诚心请教别人。&quot;</strong></p></blockquote><blockquote><p><strong>&quot;练功的姿势无论行住坐卧都可以——摆好一定的姿势，意念轻轻观察身体，同时轻轻观察自己的念头。&quot;</strong></p></blockquote><blockquote><p><strong>&quot;行住坐卧，绵绵若存——你在任何时候养成习惯都轻轻地好像似乎有点返观你的身体就对了，就是你在说话做事走路都可以养成这种轻轻返观身体的习惯，但是不能全神贯注，全神贯注反而是一种执着，而且你对外又不知道，那也很危险。&quot;</strong></p></blockquote><p>— <a href="/liaokongjushi-wisdom/60-原文段落/五篇灵文-温养章全段">五篇灵文-温养章全段</a></p><p>这四条是了空居士顿超法门的总纲。以下所有具体方法都是这四条原则的展开。</p><hr><h2 id="二、方法一-静坐-轻轻返观" tabindex="-1">二、方法一：静坐（轻轻返观） <a class="header-anchor" href="#二、方法一-静坐-轻轻返观" aria-label="Permalink to &quot;二、方法一：静坐（轻轻返观）&quot;">​</a></h2><h3 id="姿势" tabindex="-1">姿势 <a class="header-anchor" href="#姿势" aria-label="Permalink to &quot;姿势&quot;">​</a></h3><blockquote><p><strong>&quot;姿势中正安舒，不要硬撑。双盘、单盘、散盘、坐椅子都可以。&quot;</strong></p></blockquote><p>— 答疑专辑</p><h3 id="核心要诀-似守非守" tabindex="-1">核心要诀：似守非守 <a class="header-anchor" href="#核心要诀-似守非守" aria-label="Permalink to &quot;核心要诀：似守非守&quot;">​</a></h3><p>了空居士在讲解《五篇灵文》&quot;温养章&quot;时，对静坐的要诀做了最完整的说明：</p><blockquote><p><strong>&quot;神守黃房，金胎自成。黃房乃乾之下、坤之上，十二時中，念茲在茲，含光藏耀，行住坐臥，綿綿若存，如雞抱卵，如龍養珠。抱元守一，先天元神元炁，刻刻相合，漸漸相化，但安神息，不運火而火自運。&quot;</strong></p></blockquote><blockquote><p><strong>&quot;不可用心守，不可无意求。用心守则着相，无意求则落空。&quot;</strong></p></blockquote><p>— <a href="/liaokongjushi-wisdom/60-原文段落/五篇灵文-温养章全段">五篇灵文-温养章全段</a></p><p>了空居士的讲解：</p><ul><li><strong>&quot;神守黃房&quot;</strong> — 黃房是指中丹田。不是专门守膻中穴，是<strong>意守整个体腔</strong>，胸腔到腹腔。也可以膻中穴为重点，但要覆盖整个体腔</li><li><strong>&quot;不可用心守，不可无意求&quot;</strong> — 守得太紧就着相，守得太松就无效。在有心无心之间：轻轻知道，轻轻放下</li><li><strong>&quot;行住坐臥，綿綿若存&quot;</strong> — 养成轻轻返观身体的习惯，但<strong>不能全神贯注</strong>，否则既执着又危险</li><li><strong>&quot;但安神息，不運火而火自運&quot;</strong> — 只要心平气和，火候就恰到好处，自然运行</li></ul><h3 id="具体做法" tabindex="-1">具体做法 <a class="header-anchor" href="#具体做法" aria-label="Permalink to &quot;具体做法&quot;">​</a></h3><ol><li>坐好后，轻轻返观整个身体（不要太专注）</li><li>念头来了——重要的停下来想通，不重要的轻轻带过</li><li>身体发热、发麻、电流感——都正常，<strong>不追求</strong></li><li>时间：每天15分钟起步，慢慢增加到30-60分钟</li></ol><h3 id="收功" tabindex="-1">收功 <a class="header-anchor" href="#收功" aria-label="Permalink to &quot;收功&quot;">​</a></h3><blockquote><p><strong>&quot;收功的过程就是从静态慢慢恢复到动态的过程。你们原来轻轻意守手指脚趾，收功的时候其实也是同时意守手脚，只是加个意念说&#39;我要收功了，我要收功了&#39;，心里反复这么想。等到精神比较清醒了，然后全身关节活动活动，弯弯腰、伸伸腿、转转头、甩甩手腕、膝盖、脚踝……让它适应从静态到动态。&quot;</strong></p></blockquote><p>— 修行即生活（20090111b）</p><h3 id="安全提示" tabindex="-1">安全提示 <a class="header-anchor" href="#安全提示" aria-label="Permalink to &quot;安全提示&quot;">​</a></h3><ul><li>若出现头晕、胸闷、强烈不适——睁开眼睛，活动身体，<strong>不要硬撑</strong></li><li>饭后半小时内不宜静坐</li><li>发热、发麻、微电流感属正常气感，不追不拒</li></ul><hr><h2 id="三、方法二-念佛" tabindex="-1">三、方法二：念佛 <a class="header-anchor" href="#三、方法二-念佛" aria-label="Permalink to &quot;三、方法二：念佛&quot;">​</a></h2><p>了空居士传授的是<strong>心念耳闻</strong>的念佛法门，不是用计数器算数字。</p><h3 id="核心方法" tabindex="-1">核心方法 <a class="header-anchor" href="#核心方法" aria-label="Permalink to &quot;核心方法&quot;">​</a></h3><blockquote><p><strong>&quot;念佛是一边念一边发自内心向佛祖学习——诸恶莫作，众善奉行。&quot;</strong></p></blockquote><blockquote><p><strong>&quot;你只管在心中默念南无阿弥陀佛，一字一句心里清清楚楚。这就是印光大师所说的&#39;心念耳闻&#39;。&quot;</strong></p></blockquote><blockquote><p><strong>&quot;显现你在极乐，调出这个开心、这个情景，有个抽象的感觉：&#39;我也在极乐，心情很好。&#39;然后也是默默地念佛，不要出声，在心中默默地念佛。&quot;</strong></p></blockquote><p>— 念佛法门与修心问答录（20090118）</p><h3 id="具体做法-1" tabindex="-1">具体做法 <a class="header-anchor" href="#具体做法-1" aria-label="Permalink to &quot;具体做法&quot;">​</a></h3><ol><li>心里默念&quot;阿弥陀佛&quot;，耳畔听清每个字</li><li>同时显现自己在极乐——<strong>调出开心的心情</strong></li><li>有念头时，重要的想通再念；不重要的不管它，继续念</li><li>功夫深了，念而无念，无念而念（自然形成，不追求）</li></ol><h3 id="卧式练法" tabindex="-1">卧式练法 <a class="header-anchor" href="#卧式练法" aria-label="Permalink to &quot;卧式练法&quot;">​</a></h3><blockquote><p><strong>&quot;躺的时候也显现你在极乐，调出这个开心。也是默默地念佛。念着念着睡着了就睡着了，明天起来的时候，记得你要起来的时候默默再念几句佛再起来也好，忘记了随便起来也算，没事了。&quot;</strong></p></blockquote><p>— 念佛法门与修心问答录（20090118）</p><hr><h2 id="四、方法三-在日常生活中修" tabindex="-1">四、方法三：在日常生活中修 <a class="header-anchor" href="#四、方法三-在日常生活中修" aria-label="Permalink to &quot;四、方法三：在日常生活中修&quot;">​</a></h2><p>了空居士最核心的实修理念——<strong>修行不在蒲团上，在生活的每一刻</strong>。</p><blockquote><p><strong>&quot;认真工作也是禅定。生活处处是道场，为人处世样样是修行。你等一下工作做完，一盘起腿来一认认真真地念佛，本来心情就平静。一坐下来就深入境界了。一收功又去做事，又是在禅定之中做事。做完事又来练功，又是深入境界了。你每一次练功所深入禅定的境界，在日常中不容易消失。所以等于你每次练功都会觉得进步。&quot;</strong></p></blockquote><p>— 修行即生活（20090111b）</p><blockquote><p><strong>&quot;假如工作生活到处都是风风火火，到处都是神不守舍。这里心也很慌，那里心也紧张。那好，等下有空一坐下来，怎么坐都静不下去。努力地坐了半个小时、一个小时，马马虎虎能够静下来，一看时间已经过去了，腿也酸麻了。刚刚坐到有个好感觉，就已经没时间再坐下去。那好，又去工作，又去生活，把刚才得到了一点好境界马上又丢了。工作做完了，要来盘腿而坐，又会花了很大劲才能够安静下来。天天如是，这个就是竹篮打水一场空了。&quot;</strong></p></blockquote><p>— 修行即生活（20090111b）</p><h3 id="日常操作要点" tabindex="-1">日常操作要点 <a class="header-anchor" href="#日常操作要点" aria-label="Permalink to &quot;日常操作要点&quot;">​</a></h3><ol><li><strong>与人为善</strong> — 无论在哪里，这是心能安静的基础</li><li><strong>观察念头</strong> — 正确的肯定，错误的否定，解不开的请教</li><li><strong>遇事先停</strong> — 遇到烦恼，问自己&quot;我为什么要不平静？这样正确吗？&quot; <blockquote><p>原文：<a href="/liaokongjushi-wisdom/60-原文段落/金刚经5分-保持平静的要诀">金刚经5分-保持平静的要诀</a></p></blockquote></li><li><strong>空闲即修</strong> — 等电梯/排队时，轻轻返观身体，或默念几声佛号</li></ol><hr><h2 id="五、一天中的修行节奏" tabindex="-1">五、一天中的修行节奏 <a class="header-anchor" href="#五、一天中的修行节奏" aria-label="Permalink to &quot;五、一天中的修行节奏&quot;">​</a></h2><p>以下是了空居士在不同文章中对&quot;一天如何修&quot;的直接开示。每条都有原文出处。</p><h3 id="晨起" tabindex="-1">晨起 <a class="header-anchor" href="#晨起" aria-label="Permalink to &quot;晨起&quot;">​</a></h3><blockquote><p><strong>&quot;明天起来的时候，记得你要起来的时候默默再念几句佛再起来也好，忘记了随便起来也算，没事了。&quot;</strong></p></blockquote><p>— 念佛法门与修心问答录（20090118）</p><h3 id="白天——行住坐卧-绵绵若存" tabindex="-1">白天——行住坐卧，绵绵若存 <a class="header-anchor" href="#白天——行住坐卧-绵绵若存" aria-label="Permalink to &quot;白天——行住坐卧，绵绵若存&quot;">​</a></h3><blockquote><p><strong>&quot;行住坐臥，綿綿若存——你在任何时候养成习惯都轻轻地好像似乎有点返观你的身体就对了，就是你在说话做事走路都可以养成这种轻轻返观身体的习惯，但是不能全神贯注，全神贯注反而是一种执着，而且你对外又不知道，那也很危险。&quot;</strong></p></blockquote><p>— <a href="/liaokongjushi-wisdom/60-原文段落/五篇灵文-温养章全段">五篇灵文-温养章全段</a></p><blockquote><p><strong>&quot;认真工作也是禅定。生活处处是道场，为人处世样样是修行。&quot;</strong></p></blockquote><p>— 修行即生活（20090111b）</p><blockquote><p><strong>&quot;与人为善——无论在哪里，这是心能安静的基础。观察自己的念头——正确的给予肯定，错误的给予否定，解不开的诚心请教别人。&quot;</strong></p></blockquote><p>— 答疑专辑</p><h3 id="晚间——静坐或卧式念佛" tabindex="-1">晚间——静坐或卧式念佛 <a class="header-anchor" href="#晚间——静坐或卧式念佛" aria-label="Permalink to &quot;晚间——静坐或卧式念佛&quot;">​</a></h3><blockquote><p><strong>&quot;你等一下工作做完，一盘起腿来一认认真真地念佛，本来心情就平静。一坐下来就深入境界了。&quot;</strong></p></blockquote><p>— 修行即生活（20090111b）</p><blockquote><p><strong>&quot;躺的时候也显现你在极乐，调出这个开心。也是默默地念佛。念着念着睡着了就睡着了。&quot;</strong></p></blockquote><p>— 念佛法门与修心问答录（20090118）</p><hr><h2 id="六、常见误区" tabindex="-1">六、常见误区 <a class="header-anchor" href="#六、常见误区" aria-label="Permalink to &quot;六、常见误区&quot;">​</a></h2><table tabindex="0"><thead><tr><th>误区</th><th>正解</th><th>原文依据</th></tr></thead><tbody><tr><td>修行要闭关、远离社会</td><td>&quot;家庭是道场，工作单位是道场，社会是道场&quot;</td><td><a href="/liaokongjushi-wisdom/60-原文段落/金刚经1分-修行在生活中">金刚经1分-修行在生活中</a></td></tr><tr><td>静坐要&quot;入静&quot;，不能有念头</td><td>&quot;不怕念起，只怕觉迟&quot;</td><td><a href="/liaokongjushi-wisdom/60-原文段落/答疑2021-不怕念起只怕觉迟">答疑2021-不怕念起只怕觉迟</a></td></tr><tr><td>练功要调呼吸、意守丹田</td><td>&quot;但安神息，不运火而火自运&quot;</td><td><a href="/liaokongjushi-wisdom/60-原文段落/五篇灵文-温养章全段">五篇灵文-温养章全段</a></td></tr><tr><td>要追求发热、电流感</td><td>感觉是副产品，不追求。&quot;不要追求境界，境界自然会来&quot;</td><td>答疑精选</td></tr><tr><td>先修好&quot;清净心&quot;才能开始</td><td>&quot;即得不等于得后&quot;——在行中修，不是修好再行</td><td>—</td></tr></tbody></table><hr><h2 id="七、初学者常见疑问" tabindex="-1">七、初学者常见疑问 <a class="header-anchor" href="#七、初学者常见疑问" aria-label="Permalink to &quot;七、初学者常见疑问&quot;">​</a></h2><h3 id="q-我静坐时完全静不下来-杂念很多-是不是不适合修行" tabindex="-1">Q：我静坐时完全静不下来，杂念很多，是不是不适合修行？ <a class="header-anchor" href="#q-我静坐时完全静不下来-杂念很多-是不是不适合修行" aria-label="Permalink to &quot;Q：我静坐时完全静不下来，杂念很多，是不是不适合修行？&quot;">​</a></h3><blockquote><p><strong>&quot;有杂念是正常的。不怕念起，只怕觉迟。走神了——让走神，知道走神就不走神。&quot;</strong></p></blockquote><p>— <a href="/liaokongjushi-wisdom/60-原文段落/答疑2021-不怕念起只怕觉迟">答疑2021-不怕念起只怕觉迟</a></p><p>初修者最大的误区是拼命想&quot;入静&quot;。了空居士告诉你：<strong>杂念是正常的，关键是能觉察到</strong>。发现自己在走神，就已经是进步了。</p><h3 id="q-静坐了几天什么都没有感觉到-是不是没效果" tabindex="-1">Q：静坐了几天什么都没有感觉到，是不是没效果？ <a class="header-anchor" href="#q-静坐了几天什么都没有感觉到-是不是没效果" aria-label="Permalink to &quot;Q：静坐了几天什么都没有感觉到，是不是没效果？&quot;">​</a></h3><blockquote><p><strong>&quot;有一些同修练了一段时间，觉得没什么反应了。说明你的定境又比较深了。以前反应很大的时候，以道家来说属于炼精化气的阶段，是比较浅的状态。现在没什么反应了，就说明大小周天比较畅通了，开始进入炼气化神。心开始比较清净了。&quot;</strong></p></blockquote><p>— 修心与定慧等持（20090120）</p><p>所以：<strong>没感觉不代表没进步</strong>。安静本身就是功夫。&quot;但安神息，不运火而火自运&quot;——不追感觉，感觉自己会来。</p><h3 id="q-静坐时腿麻了怎么办-可以换姿势吗" tabindex="-1">Q：静坐时腿麻了怎么办？可以换姿势吗？ <a class="header-anchor" href="#q-静坐时腿麻了怎么办-可以换姿势吗" aria-label="Permalink to &quot;Q：静坐时腿麻了怎么办？可以换姿势吗？&quot;">​</a></h3><blockquote><p><strong>&quot;可以可以。姿势中正安舒，不要硬撑。&quot;</strong></p></blockquote><p>— 答疑专辑</p><h3 id="q-需要双盘吗-单盘、坐椅子行不行" tabindex="-1">Q：需要双盘吗？单盘、坐椅子行不行？ <a class="header-anchor" href="#q-需要双盘吗-单盘、坐椅子行不行" aria-label="Permalink to &quot;Q：需要双盘吗？单盘、坐椅子行不行？&quot;">​</a></h3><blockquote><p><strong>&quot;椅子都可以。其实盘坐属于阴阳平衡，比较安稳。坐椅子也可以，只要中正安舒。&quot;</strong></p></blockquote><h3 id="q-工作很忙-没时间修行怎么办" tabindex="-1">Q：工作很忙，没时间修行怎么办？ <a class="header-anchor" href="#q-工作很忙-没时间修行怎么办" aria-label="Permalink to &quot;Q：工作很忙，没时间修行怎么办？&quot;">​</a></h3><blockquote><p><strong>&quot;工作本身就是修行。认真工作也是禅定。家庭是道场，工作单位是道场。&quot;</strong></p></blockquote><p>— <a href="/liaokongjushi-wisdom/60-原文段落/金刚经1分-修行在生活中">金刚经1分-修行在生活中</a></p><h3 id="q-忘了收功-要紧吗" tabindex="-1">Q：忘了收功，要紧吗？ <a class="header-anchor" href="#q-忘了收功-要紧吗" aria-label="Permalink to &quot;Q：忘了收功，要紧吗？&quot;">​</a></h3><blockquote><p><strong>&quot;因为虽然念佛，体内内气到一定程度也会运行，大小周天也会有的。内气它是自动流转的，好像血液循环一样，没有什么地方开始、没有什么地方停止。所以收不收功都没关系。收功只是使精神和身体从静态回到动态，起一个缓冲的作用。&quot;</strong></p></blockquote><p>— 念佛法门与修心问答录（20090118）</p><hr><h2 id="八、第一个月预期" tabindex="-1">八、第一个月预期 <a class="header-anchor" href="#八、第一个月预期" aria-label="Permalink to &quot;八、第一个月预期&quot;">​</a></h2><table tabindex="0"><thead><tr><th>时间段</th><th>常见体验</th><th>应该怎么做</th></tr></thead><tbody><tr><td>第1-3天</td><td>没什么特别感觉，腿麻、杂念多</td><td>正常。坚持每天坐5-15分钟就行</td></tr><tr><td>第4-7天</td><td>可能会走神，可能忘记练</td><td>&quot;不怕念起，只怕觉迟&quot;。忘了就补回来，不批评自己</td></tr><tr><td>第2-4周</td><td>身体可能有发热、发麻、电流感；也可能什么感觉都没有</td><td>都正常。不追感觉，不担心没感觉</td></tr><tr><td>第1个月后</td><td>坐下来比以前容易安静了；做事比以前更有耐心</td><td>继续坚持。此时的安静就是功夫</td></tr></tbody></table><hr><h2 id="九、下一步" tabindex="-1">九、下一步 <a class="header-anchor" href="#九、下一步" aria-label="Permalink to &quot;九、下一步&quot;">​</a></h2><p>入门之后，可继续深入：</p><ul><li><strong>静坐深化</strong> → <a href="/liaokongjushi-wisdom/20-专题研究/topic-修行进阶">修行进阶</a> — 从入门到深入的三阶段（筑基/深入/自在大定）</li><li><strong>心法深化</strong> → 按 <a href="/liaokongjushi-wisdom/30-学习路径/path-认知路径">认知路径</a> 逐阶段学习7大核心模型</li><li><strong>概念查考</strong> → <a href="/liaokongjushi-wisdom/50-概念资料/50-概念资料_INDEX">概念词典</a> — 阅读&quot;初学推荐5步&quot;（清净心→烦恼→平常心→无为→丹田+观照）</li></ul><hr><h2 id="推荐模型" tabindex="-1">推荐模型 <a class="header-anchor" href="#推荐模型" aria-label="Permalink to &quot;推荐模型&quot;">​</a></h2><ul><li><a href="/liaokongjushi-wisdom/10-核心模型/model-性命双修">性命双修</a> — 静坐与念佛的功法原理</li><li><a href="/liaokongjushi-wisdom/10-核心模型/model-对境不住">对境不住</a> — &quot;不怕念起，只怕觉迟&quot;的心法基础</li><li><a href="/liaokongjushi-wisdom/10-核心模型/model-自然务实">自然务实</a> — &quot;做就是了&quot;的行动原则</li></ul><hr><blockquote><p>创建日期：2026-05-06 | 重写：2026-05-07（全部方法源自了空居士原始文章完整原文片段；新增总纲/收功/安全提示/初学者常见疑问/第一个月预期/下一步指引；静坐和念佛分列不再混淆；所有原话注明出处） 来源：五篇灵文讲解、修行即生活（20090111b）、念佛法门问答录（20090118）、修心与定慧等持（20090120）、答疑专辑2014/2019/2021</p></blockquote>',105)])])}const p=o(l,[["render",u]]);export{c as __pageData,p as default};
